function egalProfond(a, b) {
  // Égalité stricte pour les primitives
  if (a === b) return true;
  // Cas où l'une des valeurs est null/undefined ou les types diffèrent
  if (a === null || b === null || typeof a !== typeof b) return false;
  // Cas des tableaux
  if (Array.isArray(a) && Array.isArray(b)) {
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
      if (!egalProfond(a[i], b[i])) return false;
    }
    return true;
  }
  // Cas des objets
  if (typeof a === 'object' && typeof b === 'object') {
    const clesA = Object.keys(a);
    const clesB = Object.keys(b);
    if (clesA.length !== clesB.length) return false;
    for (const cle of clesA) {
      if (!clesB.includes(cle) || !egalProfond(a[cle], b[cle])) return false;
    }
    return true;
  }
  // Primitives différentes
  return false;
}
