function creerFilePriorite() {
  // Tableau interne représentant le min-heap, chaque élément est {val, priorite}
  const tas = [];

  function enqueue(val, priorite) {
    const element = { val, priorite };
    tas.push(element);
    // Remonter l'élément (bubble up) pour maintenir la propriété du min-heap
    let index = tas.length - 1;
    while (index > 0) {
      const parentIndex = Math.floor((index - 1) / 2);
      if (tas[index].priorite < tas[parentIndex].priorite) {
        [tas[index], tas[parentIndex]] = [tas[parentIndex], tas[index]];
        index = parentIndex;
      } else {
        break;
      }
    }
  }

  function dequeue() {
    if (tas.length === 0) return undefined;
    // La racine (index 0) est l'élément de plus petite priorité
    const min = tas[0].val;
    // Remplacer la racine par le dernier élément
    const dernier = tas.pop();
    if (tas.length > 0) {
      tas[0] = dernier;
      // Tamiser vers le bas (bubble down) pour rétablir l'ordre
      let index = 0;
      const longueur = tas.length;
      while (true) {
        const gauche = 2 * index + 1;
        const droite = 2 * index + 2;
        let plusPetit = index;
        if (gauche < longueur && tas[gauche].priorite < tas[plusPetit].priorite) {
          plusPetit = gauche;
        }
        if (droite < longueur && tas[droite].priorite < tas[plusPetit].priorite) {
          plusPetit = droite;
        }
        if (plusPetit !== index) {
          [tas[index], tas[plusPetit]] = [tas[plusPetit], tas[index]];
          index = plusPetit;
        } else {
          break;
        }
      }
    }
    return min;
  }

  function taille() {
    return tas.length;
  }

  return { enqueue, dequeue, taille };
}
```

