function creerEventEmitter() {
  // Stocke les événements et leurs listeners associés
  const evenements = {};

  function on(event, fn) {
    if (!evenements[event]) {
      evenements[event] = [];
    }
    evenements[event].push(fn);
  }

  function off(event, fn) {
    if (!evenements[event]) return;
    // Filtrer les listeners pour supprimer la fonction passée en paramètre
    evenements[event] = evenements[event].filter(listener => listener !== fn);
  }

  function emit(event, ...args) {
    if (!evenements[event]) return;
    // Copier le tableau des listeners pour éviter les problèmes si un listener se désinscrit pendant l'émission
    const listeners = [...evenements[event]];
    for (const fn of listeners) {
      fn(...args);
    }
  }

  return { on, off, emit };
}
```

