async function chargerEnParallele(urls, chargement) {
  // Lancer toutes les promesses de chargement en parallèle, sans fail-fast
  const promesses = urls.map(url => 
    chargement(url)
      .then(ressource => ({ statut: 'succes', ressource }))
      .catch(() => ({ statut: 'echec', url }))
  );
  // Attendre la résolution de toutes les promesses
  const resultats = await Promise.all(promesses);
  const succes = [];
  const echecs = [];
  // Séparer les succès et les échecs
  for (const res of resultats) {
    if (res.statut === 'succes') {
      succes.push(res.ressource);
    } else {
      echecs.push(res.url);
    }
  }
  return { succes, echecs };
}
```

