function creerSubject() {
  const abonnes = [];
  let estTermine = false;
  let aErreur = false;

  return {
    next(valeur) {
      if (estTermine || aErreur) return;
      abonnes.forEach(abonne => abonne.next?.(valeur));
    },
    error(err) {
      if (estTermine || aErreur) return;
      aErreur = true;
      estTermine = true;
      abonnes.forEach(abonne => abonne.error?.(err));
    },
    complete() {
      if (estTermine || aErreur) return;
      estTermine = true;
      abonnes.forEach(abonne => abonne.complete?.());
    },
    subscribe(observer) {
      abonnes.push(observer);
      // Retourne une fonction d'unsubscribe optionnelle
      return {
        unsubscribe() {
          const index = abonnes.indexOf(observer);
          if (index !== -1) abonnes.splice(index, 1);
        }
      };
    }
  };
}
```

