function memoiserAsync(fn) {
  const cache = new Map();
  return async function(...args) {
    // Clé de cache basée sur les arguments (adapté pour des arguments primitifs ou sérialisables)
    const cle = JSON.stringify(args);
    // Si la promesse est déjà en cache (en cours ou résolue), la retourner directement
    if (cache.has(cle)) {
      return cache.get(cle);
    }
    // Lancer l'appel et stocker la promesse en cache
    const promesse = fn(...args);
    cache.set(cle, promesse);
    try {
      return await promesse;
    } catch (erreur) {
      // Supprimer la promesse du cache en cas d'erreur pour permettre un nouveau tentatives
      cache.delete(cle);
      throw erreur;
    }
  };
}
