function creerCircuitBreaker(fn, seuil, delaiResetMs) {
  let etat = 'FERME'; // États possibles : FERME, OUVERT, DEMI_OUVERT
  let echecsConsecutifs = 0;
  let prochainEssai = Date.now();

  return async function(...args) {
    const maintenant = Date.now();

    // Gestion de l'état OUVERT : vérifier si le délai de réinitialisation est passé
    if (etat === 'OUVERT') {
      if (maintenant < prochainEssai) {
        throw new Error('Circuit ouvert, requête rejetée temporairement');
      }
      // Passer en état demi-ouvert pour tester la disponibilité du service
      etat = 'DEMI_OUVERT';
    }

    try {
      const resultat = await fn(...args);
      // Succès : réinitialiser le compteur d'échecs et revenir à l'état fermé
      echecsConsecutifs = 0;
      etat = 'FERME';
      return resultat;
    } catch (erreur) {
      // Échec : incrémenter le compteur
      echecsConsecutifs++;
      if (echecsConsecutifs >= seuil) {
        // Seuil atteint : ouvrir le circuit et définir le délai de réinitialisation
        etat = 'OUVERT';
        prochainEssai = Date.now() + delaiResetMs;
      }
      throw erreur;
    }
  };
}
