    next(valeur) {
      if (estTermine || aErreur) return;
      abonnes.forEach(abonne => abonne.next?.(valeur));
    },
    error(err) {
      if (estTermine || aErreur) return;
      aErreur = true;
      estTermine = true;
      abonnes.forEach(abonne => abonne.error?.(err));
