class LRUCache {
  constructor(capacite) {
    this.capacite = capacite;
    this.cache = new Map(); // Map conserve l'ordre d'insertion (plus ancien au début)
  }

  get(cle) {
    if (!this.cache.has(cle)) return -1;
    // Marquer la clé comme récemment utilisée en la déplaçant à la fin
    const valeur = this.cache.get(cle);
    this.cache.delete(cle);
    this.cache.set(cle, valeur);
    return valeur;
  }

  put(cle, valeur) {
    if (this.cache.has(cle)) {
      // Mettre à jour la valeur et déplacer à la fin
      this.cache.delete(cle);
    } else {
      // Évincer l'entrée la moins récemment utilisée si le cache est plein
      if (this.cache.size >= this.capacite) {
        const premiereCle = this.cache.keys().next().value;
        this.cache.delete(premiereCle);
      }
    }
    this.cache.set(cle, valeur);
  }
}
