function clonageSecurise(obj) {
  const weakMap = new WeakMap();

  function clone(val) {
    // Gérer les valeurs primitives
    if (val === null || typeof val !== 'object') return val;

    // Gérer les objets Date
    if (val instanceof Date) return new Date(val.getTime());

    // Gérer les tableaux
    if (Array.isArray(val)) {
      if (weakMap.has(val)) return weakMap.get(val);
      const cloneArray = [];
      weakMap.set(val, cloneArray);
      cloneArray.push(...val.map(item => clone(item)));
      return cloneArray;
    }

    // Gérer les objets ordinaires
    if (weakMap.has(val)) return weakMap.get(val);
    const cloneObj = {};
    weakMap.set(val, cloneObj);
    for (const cle in val) {
      if (val.hasOwnProperty(cle)) {
        cloneObj[cle] = clone(val[cle]);
      }
    }
    return cloneObj;
  }

  return clone(obj);
