    for (const noeud in distances) {
      if (!visites.has(noeud) && distances[noeud] < distMin) {
        noeudMin = noeud;
        distMin = distances[noeud];
      }
    }

    // Arrêter si tous les nœuds accessibles sont visités
    if (noeudMin === null || distMin === Infinity) break;

    visites.add(noeudMin);

    // Mettre à jour les distances des voisins
    for (const voisin in graphe[noeudMin]) {
      if (!visites.has(voisin)) {
        const nouvelleDist = distances[noeudMin] + graphe[noeudMin][voisin];
        if (nouvelleDist < distances[voisin]) {
          distances[voisin] = nouvelleDist;
        }
      }
    }
  }

