  return function curried(...args) {
    // Exécute la fonction originale si on a suffisamment d'arguments
    if (args.length >= fn.length) {
      return fn(...args);
    }
    // Sinon retourne une fonction qui accumule les arguments suivants
    return function(...nextArgs) {
      return curried(...args, ...nextArgs);
    };
  };
}

