  const evenements = {};

  function on(event, fn) {
    if (!evenements[event]) {
      evenements[event] = [];
    }
    evenements[event].push(fn);
  }

  function off(event, fn) {
    if (!evenements[event]) return;
    // Filtrer les listeners pour supprimer la fonction passée en paramètre
    evenements[event] = evenements[event].filter(listener => listener !== fn);
