async function executerAvecConcurrence(taches, maxConcurrence) {
  const resultats = new Array(taches.length);
  let indexCourant = 0;
  let tachesEnCours = 0;

  return new Promise((resolve) => {
    function executerProchaine() {
      // Toutes les tâches sont terminées
      if (indexCourant >= taches.length && tachesEnCours === 0) {
        resolve(resultats);
        return;
      }

      // Lancer de nouvelles tâches tant que la concurrence n'est pas atteinte
      while (tachesEnCours < maxConcurrence && indexCourant < taches.length) {
        const index = indexCourant++;
        tachesEnCours++;
        taches[index]().then(res => {
          resultats[index] = res;
          tachesEnCours--;
          executerProchaine();
        }).catch(err => {
          // Propager les erreurs si une tâche échoue
          tachesEnCours--;
          executerProchaine();
          throw err;
        });
