function evaluerExpression(expr) {
  let index = 0;

  function ignorerEspaces() {
    while (index < expr.length && expr[index] === ' ') index++;
  }

  function parserNombre() {
    ignorerEspaces();
    let signe = 1;
    if (expr[index] === '-') { signe = -1; index++; }
    else if (expr[index] === '+') { index++; }
    ignorerEspaces();
    let nombre = 0;
    while (index < expr.length && expr[index] >= '0' && expr[index] <= '9') {
      nombre = nombre * 10 + parseInt(expr[index]);
      index++;
    }
    return signe * nombre;
  }

  function parserFacteur() {
    ignorerEspaces();
    if (expr[index] === '(') {
      index++;
      const val = parserExpression();
      ignorerEspaces();
      if (expr[index] !== ')') throw new Error("Parenthèse fermante manquante");
      index++;
      return val;
    }
    return parserNombre();
  }

  function parserTerme() {
    let val = parserFacteur();
    ignorerEspaces();
    while (index < expr.length && (expr[index] === '*' || expr[index] === '/')) {
      const op = expr[index];
      index++;
      const droit = parserFacteur();
      val = op === '*' ? val * droit : val / droit;
      ignorerEspaces();
    }
    return val;
