  function parserExpression() {
    let val = parserTerme();
    ignorerEspaces();
    while (index < expr.length && (expr[index] === '+' || expr[index] === '-')) {
      const op = expr[index];
      index++;
      const droit = parserTerme();
      val = op === '+' ? val + droit : val - droit;
      ignorerEspaces();
    }
    return val;
  }

