    // Gérer les parenthèses
    if (expr[index] === '(') {
      index++;
      const valeur = parseExpression();
      if (expr[index] !== ')') throw new Error('Parenthèse fermante manquante');
      index++;
      return valeur;
    }

    // Gérer le moins unaire
    if (expr[index] === '-') {
      index++;
      return -parseFacteur();
    }

    // Gérer le plus unaire
    if (expr[index] === '+') {
      index++;
      return parseFacteur();
    }

    return parseNombre();
  }

  function parseTerme() {
    let valeur = parseFacteur();
    while (index < expr.length && (expr[index] === '*' || expr[index] === '/')) {
      const operateur = expr[index];
      index++;
      const droite = parseFacteur();
      if (operateur === '*') {
        valeur *= droite;
